<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {createScenarioDraft} from './scenarioDraft.js'
import {createChatObserver} from './chatObserver.js'
import Settings from './components/Settings.vue'
import IndexPanel from './components/IndexPanel.vue'
import AnswerCard from './components/AnswerCard.vue'
import {api,exportJSON,lines,dayNumbers,shouldRefreshTaskDraft,isActiveRun,runSecondsRemaining} from './view.js'
const state=ref(null),session=ref(null),busy=ref(false),error=ref(''),question=ref(''),title=ref('Мой диалог'),run=ref(null),scenarioId=ref(''),step=ref(0),scenarioLoaded=ref(false),draft=ref({goal:'',clarifications:'',constraints:'',terms:'',source_days:''})
const settings=ref({strategy:'structure',top_k_before:12,top_k_after:5,threshold:0.45})
const selectedScenario=computed(()=>state.value?.scenarios?.find(s=>s.id===scenarioId.value)), steps=computed(()=>selectedScenario.value?.turns || selectedScenario.value?.messages || selectedScenario.value?.steps || [])
const now=ref(Date.now()),chatScroll=ref(null),messageInput=ref(null),sending=ref(false)
const activeRun=computed(()=>isActiveRun(run.value))
const scenarioLocked=computed(()=>activeRun.value && session.value?.session?.id===run.value?.session_id)
const selectedPending=computed(()=>session.value?.messages?.some(m=>m.status==='pending'))
const deleteAllLocked=computed(()=>busy.value || activeRun.value || !!state.value?.active_run || selectedPending.value)
const nextSeconds=computed(()=>runSecondsRemaining(run.value,now.value))
const pendingScenarioQuestion=computed(()=>scenarioLocked.value && run.value.phase==='answering' && (session.value?.messages?.length || 0)<Number(run.value.current_question_number || 0))
let timer,clockTimer,disposed=false,refreshing=false
let pendingSubmission=null
let draftBaseline=''
function applySession(data,force=false){const changedSession=session.value?.session?.id!==data.session?.id;session.value=data;if(changedSession)scenarioDraft.reset();if(shouldRefreshTaskDraft({force,changedSession,draft:draft.value,baseline:draftBaseline})){const t=data.task_state || {};draft.value={goal:t.goal || '',clarifications:(t.clarifications||[]).join('\n'),constraints:(t.constraints||[]).join('\n'),terms:(t.terms||[]).join('\n'),source_days:(t.source_days||[]).join(', ')};draftBaseline=JSON.stringify(draft.value)}}
const scenarioDraft=createScenarioDraft({getContext:()=>({sessionId:session.value?.session?.id,scenarioId:scenarioId.value,steps:steps.value}),onDraft:text=>{question.value=text},onProgress:(count,loaded)=>{step.value=count;scenarioLoaded.value=loaded}})
function changeScenario(){scenarioDraft.reset()}
const observer=createChatObserver({api,onState(data){state.value=data;if(!scenarioId.value)scenarioId.value=data.scenarios?.[0]?.id || ''},onRun(data){run.value=data},async onSession(data){if(!data){session.value=null;scenarioDraft.reset();return}const previous=(session.value?.messages || []).map(m=>`${m.id}:${m.status}`).join('|');applySession(data);const current=(data.messages || []).map(m=>`${m.id}:${m.status}`).join('|');if((scenarioLocked.value || sending.value) && previous!==current){await nextTick();if(chatScroll.value)chatScroll.value.scrollTop=chatScroll.value.scrollHeight}}})
async function refresh(){if(refreshing)return;refreshing=true;try{await observer.refresh()}catch(e){error.value=e.message}finally{refreshing=false}}
async function poll(){await refresh();if(!disposed)timer=setTimeout(poll,activeRun.value?600:1800)}
async function action(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function select(id){return action(()=>observer.select(id))}
function create(){return action(async()=>{const data=await api('/sessions',{title:title.value});const id=data.id || data.session?.id;await observer.select(id);await refresh()})}
function saveTask(){return action(async()=>{await api(`/sessions/${session.value.session.id}/task`,{revision:session.value.revision,task_state:{goal:draft.value.goal,clarifications:lines(draft.value.clarifications),constraints:lines(draft.value.constraints),terms:lines(draft.value.terms),source_days:dayNumbers(draft.value.source_days)}},'PATCH');draftBaseline=JSON.stringify(draft.value);await observer.readSelected()})}
function resetTask(){draft.value={goal:'',clarifications:'',constraints:'',terms:'',source_days:''};return saveTask()}
async function sendValue(text){const id=session.value.session.id;if(!pendingSubmission || pendingSubmission.session_id!==id || pendingSubmission.question!==text)pendingSubmission={session_id:id,question:text,request_id:crypto.randomUUID()};const result=await api(`/sessions/${id}/messages`,{question:text,request_id:pendingSubmission.request_id,settings:settings.value});pendingSubmission=null;return result}
function send(){return action(async()=>{sending.value=true;try{const text=question.value;await scenarioDraft.send(text,sendValue);question.value='';await observer.readSelected();await refresh();await nextTick();if(chatScroll.value)chatScroll.value.scrollTop=chatScroll.value.scrollHeight}finally{sending.value=false}})}
function deletionLocked(id){return busy.value || (activeRun.value && run.value?.session_id===id) || (state.value?.active_run?.session_id===id) || (session.value?.session?.id===id && selectedPending.value)}
function remove(id=session.value?.session?.id){if(!id || deletionLocked(id))return;const name=state.value?.sessions?.find(s=>s.id===id)?.title || 'этот диалог';if(!window.confirm(`Удалить «${name}» вместе с историей и памятью?`))return;return action(async()=>{const detail=await api(`/sessions/${id}`);if(detail.messages?.some(m=>m.status==='pending'))throw new Error('Дождитесь завершения ответа перед удалением диалога.');await api(`/sessions/${id}`,undefined,'DELETE');if(session.value?.session?.id===id)await observer.select(null);await refresh();if(!session.value && state.value?.sessions?.length)await observer.select(state.value.sessions[0].id)})}
function removeAll(){if(deleteAllLocked.value || !state.value?.sessions?.length)return;if(!window.confirm('Удалить все диалоги, их историю и память? Векторный индекс останется.'))return;return action(async()=>{const latest=await api('/state');if(latest.active_run)throw new Error('Сначала остановите автопрогон.');const ids=latest.sessions.map(s=>s.id);const details=await Promise.all(ids.map(id=>api(`/sessions/${id}`)));if(details.some(s=>s.messages?.some(m=>m.status==='pending')))throw new Error('Дождитесь завершения всех ответов перед удалением.');for(const id of ids)await api(`/sessions/${id}`,undefined,'DELETE');await observer.select(null);await refresh()})}
function build(){return action(async()=>{await api('/build',{});await refresh()})}
async function nextStep(){if(busy.value || scenarioLocked.value || selectedPending.value)return;if(scenarioDraft.loadNext()){await nextTick();messageInput.value?.focus();messageInput.value?.scrollIntoView({block:"center",behavior:"smooth"})}}
function cancel(){return action(async()=>{await api(`/runs/${run.value.id}/cancel`,{});await refresh()})}
onMounted(()=>{poll();clockTimer=setInterval(()=>{now.value=Date.now()},250)})
onUnmounted(()=>{disposed=true;clearTimeout(timer);clearInterval(clockTimer)})
</script>
<template><main class="layout"><header><span class="eyebrow">ДЕНЬ 25 / RAG + ПАМЯТЬ ЗАДАЧИ</span><h1>Диалог, который сохраняет цель</h1><p>История сохраняется, память задачи собирается по ходу беседы, источники ищутся заново на каждом вопросе.</p><div class="steps"><span>Обычная беседа</span><span>Обновление памяти</span><span>Свежий поиск</span><span>Ответ с цитатами</span><span>Проверка смысла</span><span>Сохранение диалога</span></div></header><p v-if="error" class="error panel" role="alert">{{ error }}</p><IndexPanel :state="state" :busy="busy" @build="build"/><div class="chat-grid"><aside><section class="panel"><h2>Диалоги</h2><label>Название<input v-model="title" maxlength="120"></label><div class="actions"><button @click="create" :disabled="busy">Новый диалог</button></div><div class="session-list"><div v-for="s in state?.sessions || []" :key="s.id" class="session-entry"><button :class="{active:session?.session?.id===s.id}" @click="select(s.id)" :disabled="busy">{{ s.title }}</button><button class="danger session-delete" @click="remove(s.id)" :disabled="deletionLocked(s.id)" :aria-label="'Удалить диалог '+s.title" title="Удалить диалог">×</button></div></div><button class="danger" @click="removeAll" :disabled="deleteAllLocked || !state?.sessions?.length">Удалить все диалоги</button><p class="tiny">Сессии сохраняются после перезапуска. Удаление диалога не очищает векторный индекс.</p></section><section class="panel"><h2>Вопросы для демонстрации</h2><label>Сценарий<select v-model="scenarioId" @change="changeScenario" :disabled="busy"><option v-for="s in state?.scenarios || []" :key="s.id" :value="s.id">{{ s.title || s.name || s.id }}</option></select></label><p class="tiny">{{ steps.length || 15 }} пользовательских сообщений. Уточнения, ограничения и короткие продолжения.</p><p class="tiny">Отправлено {{ step }}/{{ steps.length }} вопросов выбранного сценария.</p><div class="actions"><button class="secondary" @click="nextStep" :disabled="busy || scenarioLocked || selectedPending || scenarioLoaded || !session || step>=steps.length">Подставить следующий вопрос</button></div><p class="tiny">Кнопка только заполняет поле сообщения. Проверьте или измените текст и нажмите «Отправить вопрос». Следующий вопрос будет доступен после отправки. Вопросы идут в ваш выбранный диалог.</p><p v-if="scenarioLoaded" class="tiny">Вопрос {{ step+1 }} подготовлен в поле сообщения.</p><template v-if="run"><p class="tiny">Ранее запущенный автоматический прогон. Его можно остановить.</p><div v-if="activeRun" class="scenario-progress" aria-live="polite"><b>{{ run.phase==='waiting'?'Ответ получен':'Вопрос '+(run.current_question_number || 1)+' выполняется' }}</b><p v-if="run.phase==='waiting'">Следующий вопрос через {{ nextSeconds }} сек.</p><p v-else>DeepSeek отвечает и проверяет цитаты. Ответ появится после завершения.</p><button class="secondary" v-if="session?.session?.id!==run.session_id" @click="select(run.session_id)">Показать чат сценария</button></div><p>{{ run.status }} · {{ run.progress?.current ?? run.current ?? run.results?.length ?? 0 }}/{{ run.progress?.total ?? run.total ?? 15 }}</p><button class="danger" v-if="activeRun" @click="cancel" :disabled="busy">Остановить</button><div class="actions"><button class="secondary" @click="exportJSON(run,'day25-scenario.json')">Экспорт сценария</button></div><p v-if="run.summary" class="tiny">Ответы с источниками: {{ run.summary.answered_with_sources }}/{{ run.summary.sources_denominator }} · цель зафиксирована: {{ run.summary.goal_available ?? run.summary.goal_preserved }}/{{ run.summary.goal_denominator }} · «не знаю»: {{ run.summary.unknown }} · ошибки: {{ run.summary.errors }}. Обновления памяти выполняются вместе с обычными вопросами.</p><pre v-if="run.summary">{{ JSON.stringify(run.summary,null,2) }}</pre></template></section></aside><div><template v-if="session"><section class="panel"><div class="row"><h2>{{ session.session?.title }}</h2><span class="badge">Ревизия {{ session.revision }}</span></div><h3>Память задачи · из вашей беседы</h3><p class="tiny">Цель, уточнения, ограничения и термины собираются из ваших сообщений автоматически. Отдельные команды не нужны. Если память неточна, её можно исправить.</p><div class="task-grid saved-memory"><section><b>Цель</b><p>{{ session.task_state?.goal || 'Появится по мере разговора' }}</p></section><section v-for="[field,label] in [['clarifications','Уточнения'],['constraints','Ограничения'],['terms','Термины'],['source_days','Дни источников']]" :key="field"><b>{{ label }}</b><ul v-if="session.task_state?.[field]?.length"><li v-for="(value,i) in session.task_state[field]" :key="i">{{ value }}</li></ul><p v-else class="muted">Пока не зафиксированы</p></section></div><details><summary>Исправить память вручную · необязательно</summary><label>Цель диалога<textarea v-model="draft.goal" :disabled="busy || scenarioLocked" maxlength="1200"/></label><div class="task-grid"><label>Что уже уточнили · по строке<textarea v-model="draft.clarifications" :disabled="busy || scenarioLocked"/></label><label>Ограничения · по строке<textarea v-model="draft.constraints" :disabled="busy || scenarioLocked"/></label><label>Зафиксированные термины · по строке<textarea v-model="draft.terms" :disabled="busy || scenarioLocked"/></label><label>Дни источников · 7, 9<input v-model="draft.source_days" :disabled="busy || scenarioLocked" placeholder="1–20"></label></div><div class="actions"><button @click="saveTask" :disabled="busy || scenarioLocked">Сохранить память</button><button class="secondary" @click="resetTask" :disabled="busy || scenarioLocked">Сбросить память задачи</button></div><p class="tiny">Автоматическая память опирается на ваши сообщения, а не на предположения в ответах ассистента. Явный день в вопросе имеет приоритет при поиске. Если вы редактируете поля, черновик сохраняется при новых ответах; примените его кнопкой «Сохранить память».</p></details></section><section class="panel"><div class="row"><h2>История и источники</h2><button class="secondary" @click="exportJSON(session,'day25-chat.json')">Экспорт диалога</button></div><p v-if="!session.messages?.length" class="muted">Первый вопрос начнёт историю. Источники появятся под каждым подтверждённым ответом.</p><div class="scroll" ref="chatScroll"><template v-for="(m,i) in session.messages || []" :key="m.id || i"><div v-if="m.role==='user' || m.question" class="user-message"><span class="eyebrow">ВЫ</span><p>{{ m.question || m.content }}</p></div><AnswerCard v-if="m.result" :result="m.result"/><div v-else-if="m.role==='assistant'" class="panel"><p>{{ m.content }}</p><span class="badge">{{ m.status || 'Сохранённое сообщение' }}</span></div><p v-if="['pending','interrupted'].includes(m.status)" class="tiny">{{ m.status==='pending'?'Запрос ещё выполняется.':'Запрос был прерван. Отправьте вопрос снова.' }}</p></template><div v-if="pendingScenarioQuestion" class="user-message"><span class="eyebrow">ВОПРОС СЦЕНАРИЯ {{ run.current_question_number }}</span><p>{{ run.current_question }}</p><span class="badge">Ожидаем ответ DeepSeek…</span></div></div><p v-if="scenarioLocked" class="tiny">Идёт автопрогон: вопросы появляются по одному, между ответом и следующим вопросом — 20 секунд. Можно остановить прогон слева.</p><Settings :settings="settings" :disabled="busy || scenarioLocked"/><textarea ref="messageInput" v-model="question" placeholder="Напишите обычный вопрос; цель и уточнения сохранятся по мере беседы" aria-label="Сообщение" :disabled="busy || scenarioLocked || selectedPending"/><div class="actions"><button @click="send" :disabled="busy || scenarioLocked || selectedPending || !question.trim() || !state?.index?.ready">{{ busy?'Поиск и проверка…':'Отправить вопрос' }}</button><button class="danger" @click="remove()" :disabled="deletionLocked(session.session.id)">Удалить этот диалог</button></div></section></template><section v-else class="panel"><h2>Начните с отдельного диалога</h2><p>Создайте диалог слева и начните беседу. История, автоматически собранная память и источники будут видны здесь.</p></section></div></div></main></template>
